   "在最开始来到万象站时，显色并不知道未来会如何，她只是被洪流秩序人员带着，坐上世界列车，在宇宙中飞驰。原罪从后面抱着显色，和她一起看着列车窗外的风景。“很快一切都要不一样了”“我的人生也会有所改变吗？”“或许是呢，在这边，罪恶的气息较为淡薄。”显色看向远方，太阳和月亮在这一时间完成了交接，她突然感到疲倦，有些睁不开眼。“或许是吧，一切，都会好的。”",
