   "德元曾经身为亲卫骑士团大团长，被一位摄政王看上，对方展开了疯狂的追求，而德元无法接受其不在乎生命的事实，一度想要挣脱这位摄政王的束缚。之后因为某些不可言说的故事，德元和她之间展开了激烈的交锋，最终德元离开了这个世界，而摄政王看着自己制造的废墟与惨景，只能够心碎接受。",
