  "interest": "——创作。向寓总是拥有天马行空的想法，通过画画、写字等方式实现。创作出有趣的作品，对向寓来说是最开心的事情之一。\n——聊天。向寓喜欢和不同的人聊天，了解他们的想法，交上朋友，有机会一起玩……这些都是顺其自然，很美好的事情。\n——收集\"真实洛德\"的玩偶。这是\"象棋陷阱\"系列的玩偶，以宙序管\"My Lord\"为原型设计的玩偶。小时候在安特洛帕斯的介绍下，向寓喜欢上了My Lord的故事。\n——吃陨族的菜。陨族的菜真好吃……",
