    "text": "我所期待着的，大概是\"生命的真实\"。\n去经历一些什么，去获得\"真实的幸福\"，\"幸福的真实\"。\n不要只由大众传播的\"真理\"决定，也不要被虚假的词藻和虚伪的手法所扭曲，必须是自己经过思考的，能够通过自我检验和以人为本检验的\"真实\"。\n我想去见识一些锐利、美丽、富有血肉的，我从未见识过的语言，我从未见识过的文字，至少在世上，存在给我看。\n能够与这些事物为伍，我便能感到幸福。"
