    "desc": "1、流动系（变化系）-万物拟态\n——可以让身体部位变成见过/触碰过/有研究过的生物的部分肢体。\n——对生物的结构了解越深刻，变化的越逼真。\n——无论是手、腿、头、耳朵还是别的都可以变"
