    "name": "",
    "desc": "1、流动系（属性系）-远听\n——可以清晰听到100米以内的声音，即使再微小的声音都能察觉。\n2、种族系-先珀利散打\n——先珀利的种族系能力，干练、拳拳到肉且攻守兼备的招式是核心特色。"
