  "interest": "——画画和写文。黑里森很擅长半厚涂绘画，以及给不同的动漫作品角色写同人文。她在自己的博客有80万的粉丝。而她本人觉得，没什么了不起的。\n——聊天。黑里森说自己喜欢和不同的人聊天，并从中筛选出值得聊下去的对象，还有自己可以写进作品里的信息。比如\"天镇棋和丰提润的学者在进化学上存在分歧，天镇棋学者认为他们一开始就是天镇棋，而丰提润学者认为，天镇棋有一部分是古代的丰提润进化而来的\"。\n——听ASMR。黑里森在写作的时候，会为自己营造一个放松安静的环境，在合适的环境内，才能产出合适的作品。听觉，也是环境中很重要的一部分。\n——收集\"趣事\"。黑里森喜欢听各种秘闻、趣事、传说等，不仅对写作有帮助，而且她本人也对这些非常感兴趣。",
