  "interest": "——做学术研究。李君熙真心觉得学术研究很好玩，还专门拍各种Vlog，做一些万中院的综艺，比如《万中院校长的课堂》，鼓励人们尝试从学术研究中获得乐趣。\n——开摩托。李君熙喜欢自己的鬼火摩托，她定期保养，还总是向朋友炫耀。\n——野营。李君熙喜欢野营，购买了很多昂贵且不同主题的野营道具。\n——纹身。李君熙喜欢纹身，在身体的手腕、脊背等地方拥有纹身。\n——玩。李君熙单纯喜欢玩，简单的东西也能让她玩上半天，被谏立克说在这一点特质上，万中院和赫大就很适合开学者角落会。",
