    "desc": "1、种族系-品食感情\n——拂生酩可以品食他人的感情，不同的感情，味道和质感也不同，而且可以饱腹。\n2、流动系（魔法系）——各种魔法。\n——黑费露擅长多种中阶到高阶的魔法。\n3、使魔契约\n——黑费露拥有两位使魔，可以随时召唤他们来到身边战斗，并将他们化作自己的武器。\n4、禁忌系——？？？\n——黑费露似乎拥有一些独门的禁忌系能力。"
