    "desc": "1、锻造系（科技系）-\"树家族意志\"\n——可以调动自己的能量，凭空生成科技因子构造而成的植物、花草、树木。\n——生成的数量、大小会影响自己的能量消耗。\n——可以瞬间检索面前\"植物\"的所有信息。\n——可以催熟、疗愈、增强生成的植物。\n——黎树友经常用自己的能力来修剪花草。"
