    "desc": "1、流动系（变化系）-幻化魅影。\n——一把气态的斧头，在沧海的努力下，能实现气态、液态、固态三种状态的瞬间转变，还能顺便改变至任意形态，并扩散至原本大小的一千倍。\n2、流动系（变化系）-自动痊愈。\n——身体的伤口会自行以较快的速度慢慢愈合。"
